<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])){header('Location: login.php');exit;} $id=(int)($_POST['id']??0); $pago=(string)($_POST['estado_pago']??''); $envio=(string)($_POST['estado_envio']??''); $pagos=['pendiente_validacion','aprobado','rechazado']; $envios=['pendiente','recibido','en_transito','llego','entregado']; if(!$id||!in_array($pago,$pagos,true)||!in_array($envio,$envios,true)){http_response_code(400);exit('Datos no válidos.');} $config=require __DIR__.'/config.php'; try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('UPDATE pedidos SET estado_pago=?, estado_envio=? WHERE id=?');$q->execute([$pago,$envio,$id]);header('Location: pedidos-admin.php?ok=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo actualizar el pedido.');}
